using UnityEngine;
using UnityEditor;
using UnityEngine.UIElements;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        // Toggle into play mode briefly, capture whether the HUD root
        // produces a UIDocument with rootVisualElement.
        var hud = GameObject.Find("HudRoot");
        if (hud == null) { result.Log("HudRoot missing"); return; }
        var doc = hud.GetComponent<UIDocument>();
        if (doc == null) { result.Log("UIDocument missing"); return; }
        if (doc.rootVisualElement == null)
        {
            result.Log("rootVisualElement null (edit mode). Forcing a panel settings assign.");
            var ps = AssetDatabase.LoadAssetAtPath<PanelSettings>("Assets/UI/PanelSettings.asset");
            if (ps == null) { result.Log("PanelSettings.asset missing"); return; }
            doc.panelSettings = ps;
            if (doc.rootVisualElement == null) { result.Log("still null after assign"); return; }
            result.Log("rootVisualElement after assign: ok");
        }
        else
        {
            result.Log("rootVisualElement present, child count: " + doc.rootVisualElement.childCount);
        }
    }
}
